type PaymentChoice = "paid_to_shop" | "balance_with_owner";
type OrderStatus = "in_progress" | "completed";
type ProgressReason = "work_in_progress" | "fabric_not_received" | "order_completed";
type Shop = { id: string; name: string; createdAt: string };
type Customer = { id: string; name: string | null; salesman: Salesman; address: string; mobile: string | null; createdAt: string };
type Bill = { id: string; shopId: string | null; customerId: string | null; shopName: string; customerName: string | null; customerSalesman: Salesman | null; customerAddress: string; customerMobile: string | null; stitchingAmount: number; balanceAmount: number; paymentChoice: PaymentChoice; status: OrderStatus; progressReason: ProgressReason; imageUrl: string | null; imageName: string | null; createdAt: string; updatedAt: string };
type Analytics = { totalStitchingAmount: number; totalPaidBalance: number; totalUnpaidBalance: number; deductedStitchingAmount: number };
type BillForm = { shopId: string; customerId: string; stitchingAmount: string; balanceAmount: string; paymentChoice: PaymentChoice; status: OrderStatus; progressReason: ProgressReason; imageData?: string; imageName?: string };
type DeleteTarget = { kind: "shop" | "customer" | "bill"; id: string; label: string } | null;

const reasonLabel = PROGRESS_REASON_LABELS;
const reasonTone: Record<ProgressReason, string> = { work_in_progress: "bg-[#fff0d8] text-[#93601d]", fabric_not_received: "bg-[#ffe1de] text-[#a84332]", order_completed: "bg-[#d9f0d9] text-[#1f6a38]" };
const reasonDot: Record<ProgressReason, string> = { work_in_progress: "bg-[#93601d]", fabric_not_received: "bg-[#a84332]", order_completed: "bg-[#1f6a38]" };
const statusOptions: Array<{ value: ProgressReason; label: string }> = [{ value: "work_in_progress", label: "Work in progress" }, { value: "fabric_not_received", label: "Fabric not received" }, { value: "order_completed", label: "Order completed" }];
const formatMoney = (amount = 0) => new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 }).format(amount);
const formatDate = (date: string) => new Intl.DateTimeFormat("en-IN", { day: "2-digit", month: "short", year: "numeric" }).format(new Date(date));
const shortAddress = (address: string) => { const compact = address.replace(/\s+/g, " ").trim(); return compact.length > 36 ? `${compact.slice(0, 36)}…` : compact; };
const paymentText = (bill: Pick<Bill, "paymentChoice" | "shopName">) => bill.paymentChoice === "paid_to_shop" ? `Bill paid to ${bill.shopName}` : "Mere paas balance amount hai";
const blankBill = (shops: Shop[], customers: Customer[]): BillForm => ({ shopId: shops[0]?.id ?? "", customerId: customers[0]?.id ?? "", stitchingAmount: "", balanceAmount: "", paymentChoice: "paid_to_shop", status: "in_progress", progressReason: "work_in_progress" });

async function optimiseImage(file: File) {
  if (!/^image\/(jpeg|png|webp)$/.test(file.type)) throw new Error("Only JPEG, PNG, or WebP images can be uploaded.");
  const source = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error("The image could not be read.")); reader.readAsDataURL(file); });
  const image = await new Promise<HTMLImageElement>((resolve, reject) => { const element = new Image(); element.onload = () => resolve(element); element.onerror = () => reject(new Error("The image could not be processed.")); element.src = source; });
  const ratio = Math.min(1, 1600 / Math.max(image.width, image.height));
  const canvas = document.createElement("canvas");
  canvas.width = Math.max(1, Math.round(image.width * ratio));
  canvas.height = Math.max(1, Math.round(image.height * ratio));
  canvas.getContext("2d")?.drawImage(image, 0, 0, canvas.width, canvas.height);
  return canvas.toDataURL("image/jpeg", 0.84);
}

export default function Home() {
  const { isAuthenticated } = useAuth();
  const [location, setLocation] = useLocation();
  const utils = trpc.useUtils();
  const [shopOpen, setShopOpen] = useState(false);
  const [customerOpen, setCustomerOpen] = useState(false);
  const [billOpen, setBillOpen] = useState(false);
  const [detailsOpen, setDetailsOpen] = useState(false);
  const [editingShop, setEditingShop] = useState<Shop | null>(null);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [editingBill, setEditingBill] = useState<Bill | null>(null);
  const [selectedBill, setSelectedBill] = useState<Bill | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<DeleteTarget>(null);
  const [shopName, setShopName] = useState("");
  const [customer, setCustomer] = useState<{ name: string; salesman: Salesman; address: string; mobile: string }>({ name: "", salesman: SALESMEN[0], address: "", mobile: "" });
  const [bill, setBill] = useState<BillForm>(() => blankBill([], []));
  const [imageBusy, setImageBusy] = useState(false);
  const [search, setSearch] = useState("");
  const [shopFilter, setShopFilter] = useState("all");
  const [paymentFilter, setPaymentFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const isReportsRoute = location === "/reports";
  const isOverviewRoute = location === "/";

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (window.location.pathname === "/customers" && params.get("modal") === "add") setCustomerOpen(true);
  }, []);

  const shopsQuery = trpc.billing.shops.list.useQuery(undefined, { enabled: isAuthenticated });
  const customersQuery = trpc.billing.customers.list.useQuery(undefined, { enabled: isAuthenticated });
  const dashboardQuery = trpc.billing.dashboard.useQuery(undefined, { enabled: isAuthenticated });
  const analyticsQuery = trpc.billing.analytics.useQuery(undefined, { enabled: isAuthenticated });
  const filters = useMemo(() => ({ search: search.trim() || undefined, shopId: shopFilter === "all" ? undefined : shopFilter, paymentChoice: paymentFilter === "all" ? undefined : paymentFilter as PaymentChoice, status: statusFilter === "all" ? undefined : statusFilter as OrderStatus }), [search, shopFilter, paymentFilter, statusFilter]);
  const emptyBillFilters = useMemo(() => ({}), []);
  const billsQuery = trpc.billing.bills.list.useQuery(filters, { enabled: isAuthenticated });
  const reportBillsQuery = trpc.billing.bills.list.useQuery(emptyBillFilters, { enabled: isAuthenticated && isReportsRoute });
  const monthlyBillsQuery = trpc.billing.bills.list.useQuery(emptyBillFilters, { enabled: isAuthenticated && isOverviewRoute });
  const shops = (shopsQuery.data ?? []) as Shop[];
  const customers = (customersQuery.data ?? []) as Customer[];
  const bills = (billsQuery.data ?? []) as Bill[];
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const firstCustomer = customers[0];
    if (window.location.pathname === "/customers" && params.get("modal") === "edit" && firstCustomer && !customerOpen) {
      setEditingCustomer(firstCustomer);
      setCustomer({ name: firstCustomer.name ?? "", salesman: firstCustomer.salesman, address: firstCustomer.address, mobile: firstCustomer.mobile ?? "" });
      setCustomerOpen(true);
    }
  }, [customers, customerOpen]);
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (window.location.pathname === "/bills" && params.get("modal") === "add" && shops.length && customers.length && !billOpen) {
      setEditingBill(null);
      setBill(blankBill(shops, customers));
      setBillOpen(true);
    }
  }, [shops, customers, billOpen]);
  const dashboard = dashboardQuery.data as { analytics: Analytics; shopCount: number; customerCount: number; billCount: number; activeBillCount: number; recentBills: Bill[] } | undefined;
  const analytics = analyticsQuery.data as Analytics | undefined;

  const refresh = async () => { await Promise.all([utils.billing.shops.list.invalidate(), utils.billing.customers.list.invalidate(), utils.billing.bills.list.invalidate(), utils.billing.dashboard.invalidate(), utils.billing.analytics.invalidate()]); };
  const onMutationError = (error: { message: string }) => toast.error(error.message);
  const addShop = trpc.billing.shops.create.useMutation({ onSuccess: async () => { toast.success("Shop added"); setShopOpen(false); await refresh(); }, onError: onMutationError });
  const editShop = trpc.billing.shops.update.useMutation({ onSuccess: async () => { toast.success("Shop updated"); setShopOpen(false); setEditingShop(null); await refresh(); }, onError: onMutationError });
  const deleteShop = trpc.billing.shops.delete.useMutation({ onSuccess: async () => { toast.success("Shop deleted; bill history is kept."); setDeleteTarget(null); await refresh(); }, onError: onMutationError });
  const addCustomer = trpc.billing.customers.create.useMutation({ onSuccess: async () => { toast.success("Customer added"); setCustomerOpen(false); await refresh(); }, onError: onMutationError });
  const editCustomer = trpc.billing.customers.update.useMutation({ onSuccess: async () => { toast.success("Customer updated"); setCustomerOpen(false); setEditingCustomer(null); await refresh(); }, onError: onMutationError });
  const deleteCustomer = trpc.billing.customers.delete.useMutation({ onSuccess: async () => { toast.success("Customer deleted; bill history is kept."); setDeleteTarget(null); await refresh(); }, onError: onMutationError });
  const addBill = trpc.billing.bills.create.useMutation({ onSuccess: async () => { toast.success("Bill added securely"); setBillOpen(false); setEditingBill(null); await refresh(); }, onError: onMutationError });
  const editBill = trpc.billing.bills.update.useMutation({ onSuccess: async () => { toast.success("Bill updated"); setBillOpen(false); setEditingBill(null); await refresh(); }, onError: onMutationError });
  const deleteBill = trpc.billing.bills.delete.useMutation({ onSuccess: async () => { toast.success("Bill and linked private image deleted"); setDeleteTarget(null); setDetailsOpen(false); await refresh(); }, onError: onMutationError });
  const clearBillImage = trpc.billing.bills.clearImage.useMutation({ onSuccess: async result => { toast.success("Bill image removed"); setSelectedBill(result as Bill); await refresh(); }, onError: onMutationError });
  const completeBill = trpc.billing.bills.complete.useMutation({ onSuccess: async () => { toast.success("Order marked complete"); setDetailsOpen(false); await refresh(); }, onError: onMutationError });

  const openShop = (item?: Shop) => { setEditingShop(item ?? null); setShopName(item?.name ?? ""); setShopOpen(true); };
  const openCustomer = (item?: Customer) => { setEditingCustomer(item ?? null); setCustomer(item ? { name: item.name ?? "", salesman: item.salesman, address: item.address, mobile: item.mobile ?? "" } : { name: "", salesman: SALESMEN[0], address: "", mobile: "" }); setCustomerOpen(true); };
  const openBill = (item?: Bill) => {
    if (!item && (!shops.length || !customers.length)) return toast.error("Please add at least one shop and one customer first.");
    setEditingBill(item ?? null);
    setBill(item ? { shopId: item.shopId ?? shops[0]?.id ?? "", customerId: item.customerId ?? customers[0]?.id ?? "", stitchingAmount: String(item.stitchingAmount), balanceAmount: String(item.balanceAmount), paymentChoice: item.paymentChoice, status: item.status, progressReason: item.progressReason } : blankBill(shops, customers));
    setBillOpen(true);
  };
  const chooseImage = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; setImageBusy(true); try { const imageData = await optimiseImage(file); setBill(current => ({ ...current, imageData, imageName: file.name })); toast.success("Image ready to upload"); } catch (error) { toast.error(error instanceof Error ? error.message : "Image could not be prepared."); } finally { setImageBusy(false); event.target.value = ""; } };
  const saveBill = () => { const data = { ...bill, stitchingAmount: Number(bill.stitchingAmount), balanceAmount: Number(bill.balanceAmount) }; editingBill ? editBill.mutate({ id: editingBill.id, data }) : addBill.mutate(data); };
  const confirmDelete = () => { if (!deleteTarget) return; if (deleteTarget.kind === "shop") deleteShop.mutate({ id: deleteTarget.id }); if (deleteTarget.kind === "customer") deleteCustomer.mutate({ id: deleteTarget.id }); if (deleteTarget.kind === "bill") deleteBill.mutate({ id: deleteTarget.id }); };
  const page = location === "/shops" ? "shops" : location === "/customers" ? "customers" : location === "/reports" ? "reports" : location === "/bills" ? "bills" : "overview";
  const saving = addBill.isPending || editBill.isPending || addShop.isPending || editShop.isPending || addCustomer.isPending || editCustomer.isPending;
  const error = shopsQuery.error || customersQuery.error || dashboardQuery.error || billsQuery.error || reportBillsQuery.error || monthlyBillsQuery.error;

  return <DashboardLayout>
    {error && <div className="mb-5 rounded-xl border border-[#e8c6a4] bg-[#fff5e9] px-4 py-3 text-sm text-[#80512d]">The workspace could not load: {error.message}</div>}
    {page === "overview" && <Overview dashboard={dashboard} bills={(monthlyBillsQuery.data ?? []) as Bill[]} monthlyLoading={monthlyBillsQuery.isLoading} onAdd={() => openBill()} go={setLocation} />}
    {page === "shops" && <Shops shops={shops} loading={shopsQuery.isLoading} add={() => openShop()} edit={openShop} remove={item => setDeleteTarget({ kind: "shop", id: item.id, label: item.name })} />}
    {page === "customers" && <Customers customers={customers} loading={customersQuery.isLoading} add={() => openCustomer()} edit={openCustomer} remove={item => setDeleteTarget({ kind: "customer", id: item.id, label: formatCustomerName(item.salesman, item.name) })} />}
    {page === "bills" && <Bills bills={bills} shops={shops} loading={billsQuery.isLoading} search={search} setSearch={setSearch} shopFilter={shopFilter} setShopFilter={setShopFilter} paymentFilter={paymentFilter} setPaymentFilter={setPaymentFilter} statusFilter={statusFilter} setStatusFilter={setStatusFilter} add={() => openBill()} view={item => { setSelectedBill(item); setDetailsOpen(true); }} edit={openBill} remove={item => setDeleteTarget({ kind: "bill", id: item.id, label: `bill for ${formatCustomerName(item.customerSalesman, item.customerName)}` })} />}
    {page === "reports" && <Reports bills={(reportBillsQuery.data ?? []) as Bill[]} loading={reportBillsQuery.isLoading} />}
    <Dialog open={shopOpen} onOpenChange={setShopOpen}><DialogContent className="sm:max-w-md"><DialogHeader><DialogTitle>{editingShop ? "Edit shop" : "Add shop"}</DialogTitle><DialogDescription>Shop names appear in your new bills.</DialogDescription></DialogHeader><div className="grid gap-2"><Label htmlFor="shop-name">Shop name</Label><Input id="shop-name" value={shopName} onChange={event => setShopName(event.target.value)} placeholder="e.g. Noor Boutique" autoFocus /></div><DialogFooter><Button variant="outline" onClick={() => setShopOpen(false)}>Cancel</Button><Button disabled={!shopName.trim() || saving} onClick={() => editingShop ? editShop.mutate({ id: editingShop.id, name: shopName }) : addShop.mutate({ name: shopName })}>{saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}{editingShop ? "Save changes" : "Add shop"}</Button></DialogFooter></DialogContent></Dialog>
    <Dialog open={customerOpen} onOpenChange={setCustomerOpen}><DialogContent className="sm:max-w-lg"><DialogHeader><DialogTitle>{editingCustomer ? "Edit customer" : "Add customer"}</DialogTitle><DialogDescription>These details are saved to the customer profile and the bill record.</DialogDescription></DialogHeader><div className="grid gap-4"><div className="grid gap-4 sm:grid-cols-[1.2fr_.8fr]"><Field label="Customer name"><Input value={customer.name} onChange={event => setCustomer(current => ({ ...current, name: event.target.value }))} placeholder="Customer full name" /></Field><Field label="Salesman"><Drop value={customer.salesman} set={value => setCustomer(current => ({ ...current, salesman: value as Salesman }))} items={SALESMEN.map(item => ({ value: item, label: item }))} /></Field></div><Field label="Address"><Textarea value={customer.address} onChange={event => setCustomer(current => ({ ...current, address: event.target.value }))} placeholder="House, area, city" /></Field><Field label="Mobile number"><Input inputMode="tel" value={customer.mobile} onChange={event => setCustomer(current => ({ ...current, mobile: event.target.value }))} placeholder="98765 43210" /></Field></div><DialogFooter><Button variant="outline" onClick={() => setCustomerOpen(false)}>Cancel</Button><Button disabled={!customer.address.trim() || saving} onClick={() => editingCustomer ? editCustomer.mutate({ id: editingCustomer.id, ...customer }) : addCustomer.mutate(customer)}>{saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}{editingCustomer ? "Save changes" : "Add customer"}</Button></DialogFooter></DialogContent></Dialog>
    <BillFormDialog open={billOpen} setOpen={setBillOpen} bill={bill} setBill={setBill} shops={shops} customers={customers} existing={editingBill} imageBusy={imageBusy} chooseImage={chooseImage} save={saveBill} saving={addBill.isPending || editBill.isPending} />
    <BillDetails open={detailsOpen} setOpen={setDetailsOpen} bill={selectedBill} edit={item => { setDetailsOpen(false); openBill(item); }} remove={item => setDeleteTarget({ kind: "bill", id: item.id, label: `bill for ${formatCustomerName(item.customerSalesman, item.customerName)}` })} clearImage={item => clearBillImage.mutate({ id: item.id })} clearingImage={clearBillImage.isPending} complete={item => completeBill.mutate({ id: item.id })} completing={completeBill.isPending} />
    <Dialog open={!!deleteTarget} onOpenChange={value => !value && setDeleteTarget(null)}><DialogContent className="sm:max-w-md"><DialogHeader><DialogTitle>Delete {deleteTarget?.kind}?</DialogTitle><DialogDescription>This will permanently remove <strong>{deleteTarget?.label}</strong>. Existing bills preserve their recorded history if a shop or customer is deleted.</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={() => setDeleteTarget(null)}>Cancel</Button><Button variant="destructive" onClick={confirmDelete} disabled={deleteShop.isPending || deleteCustomer.isPending || deleteBill.isPending}>Delete</Button></DialogFooter></DialogContent></Dialog>
  </DashboardLayout>;
}

function Overview({ dashboard, bills, monthlyLoading, onAdd, go }: { dashboard?: { analytics: Analytics; shopCount: number; customerCount: number; billCount: number; activeBillCount: number; recentBills: Bill[] }; bills: Bill[]; monthlyLoading: boolean; onAdd: () => void; go: (path: string) => void }) { return <div className="mx-auto max-w-7xl space-y-7"><section className="relative overflow-hidden rounded-[2rem] bg-[#173621] px-6 py-8 text-[#fffdf7] shadow-[0_25px_60px_-25px_rgba(16,46,27,.55)] sm:px-9 sm:py-10"><div className="absolute -right-20 -top-20 h-64 w-64 rounded-full bg-[#c7ed6a]/10 blur-3xl" /><div className="relative flex flex-col gap-6 lg:flex-row lg:items-end lg:justify-between"><div><p className="font-mono text-[11px] uppercase tracking-[.16em] text-[#c7ed6a]">Silai Ledger · secure workspace</p><h1 className="mt-3 font-display text-4xl leading-[1.05] sm:text-5xl">Make every stitch<br />account for something.</h1><p className="mt-4 max-w-md text-sm leading-6 text-[#d2ded4]">A refined view of shop balances, order progress, and the people behind every bill.</p></div><Button onClick={onAdd} className="h-12 rounded-xl bg-[#c7ed6a] px-5 text-[#102018] hover:bg-[#d9f48f]"><Plus className="mr-2 h-4 w-4" />Add new bill</Button></div></section><MetricGrid analytics={dashboard?.analytics} /><MonthlySummaries bills={bills} loading={monthlyLoading} /><div className="grid gap-6 lg:grid-cols-[1.35fr_.65fr]"><Card className="border-[#ded8ca] bg-white/80 shadow-sm"><CardContent className="p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="font-display text-2xl text-[#183322]">Recent bill activity</p><p className="mt-1 text-sm text-muted-foreground">Latest secure records in your workspace</p></div><Button variant="ghost" className="text-[#356944]" onClick={() => go("/bills")}>View all</Button></div><div className="mt-5 divide-y divide-[#ede8de]">{dashboard?.recentBills?.length ? dashboard.recentBills.map(item => <CompactBill bill={item} key={item.id} />) : <Empty icon={FileText} title="No bills yet" text="Add shops and customers, then create your first bill." />}</div></CardContent></Card><Card className="border-[#ded8ca] bg-[#ede9de] shadow-sm"><CardContent className="p-5 sm:p-6"><p className="font-display text-2xl text-[#183322]">Workspace pulse</p><p className="mt-1 text-sm text-[#687568]">At a glance</p><div className="mt-6 space-y-3"><Pulse icon={PackageCheck} label="Active orders" value={dashboard?.activeBillCount ?? 0} /><Pulse icon={Store} label="Shops managed" value={dashboard?.shopCount ?? 0} /><Pulse icon={UsersRound} label="Customers saved" value={dashboard?.customerCount ?? 0} /></div><Button variant="outline" className="mt-6 w-full border-[#b9c2ae] bg-white/60 text-[#254b31] hover:bg-white" onClick={() => go("/reports")}>Open reports</Button></CardContent></Card></div></div>; }

function MetricGrid({ analytics }: { analytics?: Analytics }) { const items = [{ label: "Total stitching", value: analytics?.totalStitchingAmount ?? 0, note: "Across all bills", icon: "✂", tint: "bg-[#e7f6b9] text-[#355723]" }, { label: "Paid balance", value: analytics?.totalPaidBalance ?? 0, note: "Paid to shops", icon: CheckCircle2, tint: "bg-[#d9eee1] text-[#225f38]" }, { label: "Unpaid balance", value: analytics?.totalUnpaidBalance ?? 0, note: "Held by owner", icon: WalletCards, tint: "bg-[#f3e0cc] text-[#85491e]" }, { label: "50% deducted stitching", value: analytics?.deductedStitchingAmount ?? 0, note: "Calculated automatically", icon: CircleDollarSign, tint: "bg-[#e5e7fa] text-[#4b5294]" }]; return <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{items.map(item => <Card className="border-[#ded8ca] bg-white/80 shadow-sm" key={item.label}><CardContent className="p-5"><div className="flex items-start justify-between"><div><p className="text-[10px] font-semibold uppercase tracking-[.12em] text-[#708073]">{item.label}</p><p className="mt-3 font-display text-3xl text-[#183322]">{formatMoney(item.value)}</p><p className="mt-1 text-xs text-muted-foreground">{item.note}</p></div><div className={`grid h-10 w-10 place-items-center rounded-xl ${item.tint}`}>{typeof item.icon === "string" ? <span className="text-xl">{item.icon}</span> : <item.icon className="h-5 w-5" />}</div></div></CardContent></Card>)}</section>; }
function MonthlySummaries({ bills, loading }: { bills: Bill[]; loading: boolean }) { const summaries = useMemo(() => getRecentMonthlySummaries(bills, 6), [bills]); const currentKey = summaries[summaries.length - 1]?.key; return <section><div className="mb-4 flex flex-col gap-1 sm:flex-row sm:items-end sm:justify-between"><div><p className="font-display text-2xl text-[#183322]">Monthly performance</p><p className="mt-1 text-sm text-muted-foreground">A six-month view of your stitching work and balances.</p></div><p className="text-xs font-medium uppercase tracking-[.12em] text-[#658466]">Last 6 months</p></div>{loading ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><Loading count={6} /></div> : <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{summaries.map(summary => <Card key={summary.key} className={`overflow-hidden border-[#ded8ca] shadow-sm ${summary.key === currentKey ? "bg-[#e8f1d9]" : "bg-white/80"}`}><CardContent className="p-5"><div className="flex items-center justify-between"><div><p className="font-display text-xl text-[#1d3927]">{summary.label}</p><p className="mt-1 text-xs text-muted-foreground">{summary.billCount} {summary.billCount === 1 ? "bill" : "bills"} recorded</p></div><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#c7ed6a] text-[#24442a]"><BarChart3 className="h-4 w-4" /></div></div><div className="mt-5 grid grid-cols-2 gap-4"><Amount label="Stitching" value={formatMoney(summary.totalStitchingAmount)} /><Amount label="Paid balance" value={formatMoney(summary.totalPaidBalance)} /></div><div className="mt-4 flex items-center justify-between border-t border-[#dce6d4] pt-3 text-xs text-[#5b705e]"><span>Owner balance: <strong className="text-[#305337]">{formatMoney(summary.totalUnpaidBalance)}</strong></span><span>{summary.completedCount} complete · {summary.inProgressCount} active</span></div></CardContent></Card>)}</div>}</section>; }

function Shops({ shops, loading, add, edit, remove }: { shops: Shop[]; loading: boolean; add: () => void; edit: (item: Shop) => void; remove: (item: Shop) => void }) { return <Page title="Your shops" eyebrow="Directory" text="Keep shop names ready for clean, accurate billing." action={<Button onClick={add}><Plus className="mr-2 h-4 w-4" />Add shop</Button>}><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{loading ? <Loading count={3} /> : shops.length ? shops.map(item => <Card className="group border-[#ded8ca] bg-white/80 shadow-sm" key={item.id}><CardContent className="p-5"><div className="flex justify-between"><div className="grid h-11 w-11 place-items-center rounded-xl bg-[#e9f5bd] text-[#315c2f]"><Store className="h-5 w-5" /></div><Actions edit={() => edit(item)} remove={() => remove(item)} /></div><p className="mt-7 font-display text-2xl text-[#1a3624]">{item.name}</p><p className="mt-2 text-xs text-muted-foreground">Added {formatDate(item.createdAt)}</p></CardContent></Card>) : <div className="sm:col-span-2 xl:col-span-3"><Empty icon={Store} title="No shops added" text="Create your first shop, then assign it to new bills." action={<Button onClick={add}><Plus className="mr-2 h-4 w-4" />Add shop</Button>} /></div>}</div></Page>; }

function Customers({ customers, loading, add, edit, remove }: { customers: Customer[]; loading: boolean; add: () => void; edit: (item: Customer) => void; remove: (item: Customer) => void }) { return <Page title="Your customers" eyebrow="Directory" text="Save customer name, salesman, address, and mobile number for every bill." action={<Button onClick={add}><Plus className="mr-2 h-4 w-4" />Add customer</Button>}><div className="grid gap-4 lg:grid-cols-2">{loading ? <Loading count={4} /> : customers.length ? customers.map(item => <Card className="group border-[#ded8ca] bg-white/80 shadow-sm" key={item.id}><CardContent className="p-5"><div className="flex gap-3"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-[#e0efe3] text-[#31613c]"><UserRound className="h-5 w-5" /></div><div className="min-w-0 flex-1"><p className="font-display text-2xl text-[#1a3624]">{formatCustomerName(item.salesman, item.name)}</p><p className="mt-3 flex gap-2 text-sm text-[#637364]"><MapPin className="mt-0.5 h-4 w-4 shrink-0 text-[#7c9b7e]" />{item.address}</p><p className="mt-2 flex items-center gap-2 text-sm text-[#637364]"><Phone className="h-4 w-4 text-[#7c9b7e]" />{item.mobile}</p></div><Actions edit={() => edit(item)} remove={() => remove(item)} /></div></CardContent></Card>) : <div className="lg:col-span-2"><Empty icon={UsersRound} title="No customers yet" text="Create your first customer before adding a bill." action={<Button onClick={add}><Plus className="mr-2 h-4 w-4" />Add customer</Button>} /></div>}</div></Page>; }

function Bills({ bills, shops, loading, search, setSearch, shopFilter, setShopFilter, paymentFilter, setPaymentFilter, statusFilter, setStatusFilter, add, view, edit, remove }: { bills: Bill[]; shops: Shop[]; loading: boolean; search: string; setSearch: (value: string) => void; shopFilter: string; setShopFilter: (value: string) => void; paymentFilter: string; setPaymentFilter: (value: string) => void; statusFilter: string; setStatusFilter: (value: string) => void; add: () => void; view: (item: Bill) => void; edit: (item: Bill) => void; remove: (item: Bill) => void }) { return <Page title="Bills & orders" eyebrow="Billing register" text="Search across customer name, amount, address, and mobile number." action={<Button onClick={add}><Plus className="mr-2 h-4 w-4" />Add bill</Button>}><Card className="mb-5 border-[#ded8ca] bg-white/75 shadow-sm"><CardContent className="grid gap-3 p-4 lg:grid-cols-[1.5fr_.85fr_.85fr_.85fr]"><div className="relative"><Search className="absolute left-3 top-3 h-4 w-4 text-[#799079]" /><Input className="h-10 border-[#ded8ca] bg-white pl-9" value={search} onChange={event => setSearch(event.target.value)} placeholder="Search name, amount, address, mobile..." /></div><Drop value={shopFilter} set={setShopFilter} items={[{ value: "all", label: "All shops" }, ...shops.map(item => ({ value: item.id, label: item.name }))]} /><Drop value={paymentFilter} set={setPaymentFilter} items={[{ value: "all", label: "All payments" }, { value: "paid_to_shop", label: "Paid to shop" }, { value: "balance_with_owner", label: "Balance with owner" }]} /><Drop value={statusFilter} set={setStatusFilter} items={[{ value: "all", label: "All statuses" }, { value: "in_progress", label: "In progress" }, { value: "completed", label: "Completed" }]} /></CardContent></Card><div className="space-y-3">{loading ? <Loading count={4} /> : bills.length ? bills.map(item => <BillCard bill={item} key={item.id} view={view} edit={edit} remove={remove} />) : <Empty icon={FileText} title="No bills found" text="Try a different filter, or add a bill to your register." action={<Button onClick={add}><Plus className="mr-2 h-4 w-4" />Add bill</Button>} />}</div></Page>; }

function Reports({ bills, loading }: { bills: Bill[]; loading: boolean }) {
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const invalidRange = Boolean(from && to && from > to);
  const filteredBills: Bill[] = useMemo(() => invalidRange ? [] : filterBillsByDate(bills, from || undefined, to || undefined), [bills, from, invalidRange, to]);
  const analytics = useMemo(() => calculateReportAnalytics(filteredBills), [filteredBills]);
  const rows = [{ label: "Total stitching", value: analytics.totalStitchingAmount, color: "bg-[#466f48]" }, { label: "Paid balance", value: analytics.totalPaidBalance, color: "bg-[#91bc59]" }, { label: "Unpaid balance", value: analytics.totalUnpaidBalance, color: "bg-[#d78e58]" }, { label: "50% deducted stitching", value: analytics.deductedStitchingAmount, color: "bg-[#8784c2]" }];
  const max = Math.max(...rows.map(row => row.value), 1);
  const selection = from || to ? `${from || "all-time"}_to_${to || "today"}` : "all-time";
  const exportCsv = () => {
    if (loading) return;
    const blob = new Blob([buildReportCsv(filteredBills)], { type: "text/csv;charset=utf-8" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `silai-ledger-report-${selection}.csv`;
    link.click();
    URL.revokeObjectURL(link.href);
    toast.success(`${filteredBills.length} report ${filteredBills.length === 1 ? "record" : "records"} exported as CSV`);
  };
  return <Page title="Reports & analytics" eyebrow="Financial overview" text="Choose a date range to recalculate each figure, then export the same report data as CSV." action={<Button variant="outline" disabled={invalidRange || loading} onClick={exportCsv}>{loading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Download className="mr-2 h-4 w-4" />}{loading ? "Preparing report" : "Export CSV"}</Button>}>
    <Card className="mb-6 border-[#ded8ca] bg-white/80 shadow-sm"><CardContent className="p-4 sm:p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div className="grid gap-3 sm:grid-cols-2"><Field label="From date"><Input type="date" value={from} onChange={event => setFrom(event.target.value)} /></Field><Field label="To date"><Input type="date" value={to} onChange={event => setTo(event.target.value)} /></Field></div><div className="flex flex-wrap gap-2"><Button type="button" variant="ghost" size="sm" disabled={loading || (!from && !to)} onClick={() => { setFrom(""); setTo(""); }}>Clear range</Button><Button type="button" variant="outline" size="sm" disabled={invalidRange || loading} onClick={exportCsv}>{loading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Download className="mr-2 h-4 w-4" />}{loading ? "Preparing report" : "Export selected"}</Button></div></div>{invalidRange ? <p className="mt-3 text-sm text-destructive">The “From date” must be on or before the “To date”.</p> : loading ? <p className="mt-3 flex items-center gap-2 text-xs text-muted-foreground"><Loader2 className="h-3.5 w-3.5 animate-spin" />Loading your complete bill ledger…</p> : <p className="mt-3 text-xs text-muted-foreground">Showing <strong>{filteredBills.length}</strong> bill {filteredBills.length === 1 ? "record" : "records"} for {from || to ? "the selected period" : "all time"}. The CSV export uses this same selection.</p>}</CardContent></Card>
    {loading ? <ReportLoading /> : <><MetricGrid analytics={analytics} />
    <div className="mt-7 grid gap-6 lg:grid-cols-[1.15fr_.85fr]"><Card className="border-[#ded8ca] bg-white/80 shadow-sm"><CardContent className="p-5 sm:p-7"><p className="font-display text-2xl text-[#1b3624]">Balance distribution</p><p className="mt-1 text-sm text-muted-foreground">Totals for the selected period.</p><div className="mt-8 space-y-6">{rows.map(row => <div key={row.label}><div className="mb-2 flex justify-between text-sm"><span className="font-medium text-[#526355]">{row.label}</span><span className="font-semibold text-[#263f2c]">{formatMoney(row.value)}</span></div><div className="h-3 overflow-hidden rounded-full bg-[#edf0e8]"><div className={`h-full rounded-full ${row.color}`} style={{ width: `${Math.min(100, row.value / max * 100)}%` }} /></div></div>)}</div></CardContent></Card><Card className="border-[#ded8ca] bg-[#e6eedf] shadow-sm"><CardContent className="p-5 sm:p-7"><p className="font-display text-2xl text-[#1b3624]">Order progress</p><p className="mt-1 text-sm text-[#667367]">Status inside the selected range.</p><div className="mt-7 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-white/70 p-4"><p className="text-xs uppercase tracking-[.12em] text-[#668168]">In progress</p><p className="mt-2 font-display text-4xl text-[#29472f]">{filteredBills.filter(item => item.status === "in_progress").length}</p></div><div className="rounded-2xl bg-white/70 p-4"><p className="text-xs uppercase tracking-[.12em] text-[#668168]">Completed</p><p className="mt-2 font-display text-4xl text-[#29472f]">{filteredBills.filter(item => item.status === "completed").length}</p></div></div><p className="mt-8 border-t border-[#cbd7c6] pt-5 text-xs leading-5 text-[#637364]">Paid balance contains bills marked <strong>Bill paid to shop</strong>. Unpaid balance contains bills marked <strong>Mere paas balance amount hai</strong>.</p></CardContent></Card></div></>}
  </Page>;
}

function BillFormDialog({ open, setOpen, bill, setBill, shops, customers, existing, imageBusy, chooseImage, save, saving }: { open: boolean; setOpen: (value: boolean) => void; bill: BillForm; setBill: React.Dispatch<React.SetStateAction<BillForm>>; shops: Shop[]; customers: Customer[]; existing: Bill | null; imageBusy: boolean; chooseImage: (event: ChangeEvent<HTMLInputElement>) => void; save: () => void; saving: boolean }) { const selectedShop = shops.find(item => item.id === bill.shopId); const preview = bill.imageData ?? existing?.imageUrl; const valid = Boolean(bill.shopId && bill.customerId && bill.stitchingAmount !== "" && bill.balanceAmount !== "" && !imageBusy); return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="max-h-[92svh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle>{existing ? "Edit bill details" : "Add new bill"}</DialogTitle><DialogDescription>Payment choice and order progress reason are required for every bill.</DialogDescription></DialogHeader><div className="grid gap-5 py-2 sm:grid-cols-2"><Field label="Shop"><Drop value={bill.shopId} set={value => setBill(current => ({ ...current, shopId: value }))} items={shops.map(item => ({ value: item.id, label: item.name }))} placeholder="Select a shop" /></Field><Field label="Customer"><Drop value={bill.customerId} set={value => setBill(current => ({ ...current, customerId: value }))} items={customers.map(item => ({ value: item.id, label: `${formatCustomerName(item.salesman, item.name)} · ${shortAddress(item.address)}` }))} placeholder="Select a customer" /></Field><Field label="Stitching amount"><Input type="number" min="0" inputMode="decimal" value={bill.stitchingAmount} onChange={event => setBill(current => ({ ...current, stitchingAmount: event.target.value }))} placeholder="0" /></Field><Field label="Balance amount"><Input type="number" min="0" inputMode="decimal" value={bill.balanceAmount} onChange={event => setBill(current => ({ ...current, balanceAmount: event.target.value }))} placeholder="0" /></Field><div className="grid gap-2 sm:col-span-2"><Label>Payment choice</Label><Drop value={bill.paymentChoice} set={value => setBill(current => ({ ...current, paymentChoice: value as PaymentChoice }))} items={[{ value: "paid_to_shop", label: `Bill paid to ${selectedShop?.name ?? "selected shop"}` }, { value: "balance_with_owner", label: "Mere paas balance amount hai" }]} /></div><div className="grid gap-2 sm:col-span-2"><Label>Order status / reason</Label><StatusDrop value={bill.progressReason} set={value => setBill(current => ({ ...current, progressReason: value, status: value === "order_completed" ? "completed" : "in_progress" }))} /><p className="text-xs text-muted-foreground">A progress reason is required. Completed bills use Order completed.</p></div><div className="sm:col-span-2"><Label>Bill / order image</Label><div className="mt-2 flex flex-col gap-3 rounded-2xl border border-dashed border-[#bbc6b5] bg-[#f6f8f2] p-4 sm:flex-row sm:items-center">{preview ? <img src={preview} alt="Bill preview" className="h-24 w-24 rounded-xl object-cover" /> : <div className="grid h-24 w-24 place-items-center rounded-xl bg-white text-[#759377]"><ImagePlus className="h-7 w-7" /></div>}<div><p className="font-medium text-[#38503b]">{bill.imageName ?? existing?.imageName ?? "No image selected"}</p><p className="mt-1 text-xs text-muted-foreground">JPEG, PNG, or WebP. Stored privately in Supabase.</p><Label htmlFor="image-file" className="mt-3 inline-flex h-9 cursor-pointer items-center rounded-lg bg-[#21432b] px-3 text-sm font-medium text-white hover:bg-[#183522]">{imageBusy ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <ImagePlus className="mr-2 h-4 w-4" />}{preview ? "Replace photo" : "Upload photo"}</Label><Input id="image-file" type="file" accept="image/jpeg,image/png,image/webp" className="hidden" onChange={chooseImage} /></div></div></div></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancel</Button><Button disabled={!valid || saving} onClick={save}>{saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}{existing ? "Save bill changes" : "Add bill"}</Button></DialogFooter></DialogContent></Dialog>; }

function BillDetails({ open, setOpen, bill, edit, remove, clearImage, clearingImage, complete, completing }: { open: boolean; setOpen: (value: boolean) => void; bill: Bill | null; edit: (item: Bill) => void; remove: (item: Bill) => void; clearImage: (item: Bill) => void; clearingImage: boolean; complete: (item: Bill) => void; completing: boolean }) { if (!bill) return null; return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="max-h-[92svh] overflow-y-auto sm:max-w-2xl"><DialogHeader><div className="flex items-center gap-3"><DialogTitle>Bill details</DialogTitle><State status={bill.status} reason={bill.progressReason} /></div><DialogDescription>Created {formatDate(bill.createdAt)} · Updated {formatDate(bill.updatedAt)}</DialogDescription></DialogHeader><div className="grid gap-5 sm:grid-cols-[.9fr_1.1fr]"><div className="overflow-hidden rounded-2xl bg-[#edf0e8]">{bill.imageUrl ? <img src={bill.imageUrl} alt={`Bill for ${formatCustomerName(bill.customerSalesman, bill.customerName)}`} className="h-60 w-full object-cover" /> : <div className="grid h-60 place-items-center text-[#809681]"><FileImage className="h-8 w-8" /></div>}</div><div className="space-y-4"><Detail icon={UserRound} label="Customer" value={formatCustomerName(bill.customerSalesman, bill.customerName)} /><Detail icon={MapPin} label="Address" value={bill.customerAddress} /><Detail icon={Phone} label="Mobile number" value={bill.customerMobile ?? "Not provided"} /><Detail icon={Store} label="Shop" value={bill.shopName} /><Detail icon={PackageCheck} label="Order reason" value={reasonLabel[bill.progressReason]} /></div></div>{bill.imageUrl && <Button variant="outline" className="w-full border-[#e6c9c2] text-[#a84332] hover:bg-[#fff1ee] hover:text-[#a84332]" disabled={clearingImage} onClick={() => clearImage(bill)}>{clearingImage && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}<X className="mr-2 h-4 w-4" />Remove photo only</Button>}<div className="grid gap-3 rounded-2xl bg-[#eff3e9] p-4 sm:grid-cols-3"><Amount label="Stitching amount" value={formatMoney(bill.stitchingAmount)} /><Amount label="Balance amount" value={formatMoney(bill.balanceAmount)} /><div><p className="text-[10px] font-semibold uppercase tracking-[.12em] text-[#809080]">Payment state</p><p className="mt-1 text-sm font-semibold text-[#25402c]">{paymentText(bill)}</p></div></div><DialogFooter className="gap-2 sm:justify-between"><Button variant="destructive" onClick={() => remove(bill)}><Trash2 className="mr-2 h-4 w-4" />Delete</Button><div className="flex gap-2"><Button variant="outline" onClick={() => edit(bill)}><Edit3 className="mr-2 h-4 w-4" />Edit / replace photo</Button>{bill.status === "in_progress" && <Button disabled={completing} onClick={() => complete(bill)}>{completing && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}<CheckCircle2 className="mr-2 h-4 w-4" />Mark complete</Button>}</div></DialogFooter></DialogContent></Dialog>; }

function Page({ title, eyebrow, text, action, children }: { title: string; eyebrow: string; text: string; action?: React.ReactNode; children: React.ReactNode }) { return <div className="mx-auto max-w-7xl"><header className="mb-7 flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><p className="font-mono text-[11px] font-semibold uppercase tracking-[.16em] text-[#5b865d]">{eyebrow}</p><h1 className="mt-2 font-display text-4xl text-[#1a3624] sm:text-5xl">{title}</h1><p className="mt-3 max-w-xl text-sm leading-6 text-[#667367]">{text}</p></div>{action}</header>{children}</div>; }
function Drop({ value, set, items, placeholder }: { value: string; set: (value: string) => void; items: { value: string; label: string }[]; placeholder?: string }) { return <Select value={value} onValueChange={set}><SelectTrigger className="h-10 border-[#ded8ca] bg-white"><SelectValue placeholder={placeholder ?? "Select"} /></SelectTrigger><SelectContent>{items.map(item => <SelectItem key={item.value} value={item.value}>{item.label}</SelectItem>)}</SelectContent></Select>; }
function StatusDrop({ value, set }: { value: ProgressReason; set: (value: ProgressReason) => void }) { return <Select value={value} onValueChange={next => set(next as ProgressReason)}><SelectTrigger className="h-10 border-[#ded8ca] bg-white"><div className="flex items-center gap-2"><span aria-hidden="true" className={`h-2 w-2 rounded-full ${reasonDot[value]}`} />{reasonLabel[value]}</div></SelectTrigger><SelectContent>{statusOptions.map(item => <SelectItem key={item.value} value={item.value}><span className="flex items-center gap-2"><span aria-hidden="true" className={`h-2 w-2 rounded-full ${reasonDot[item.value]}`} />{item.label}</span></SelectItem>)}</SelectContent></Select>; }
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <div className="grid gap-2"><Label>{label}</Label>{children}</div>; }
function Actions({ edit, remove }: { edit: () => void; remove: () => void }) { return <div className="flex gap-1"><Button variant="ghost" size="icon" onClick={edit} aria-label="Edit"><Edit3 className="h-4 w-4" /></Button><Button variant="ghost" size="icon" onClick={remove} aria-label="Delete" className="text-destructive hover:text-destructive"><Trash2 className="h-4 w-4" /></Button></div>; }
function BillCard({ bill, view, edit, remove }: { bill: Bill; view: (item: Bill) => void; edit: (item: Bill) => void; remove: (item: Bill) => void }) { return <Card className="border-[#ded8ca] bg-white/80 shadow-sm"><CardContent className="p-4 sm:p-5"><div className="flex flex-col gap-4 xl:flex-row xl:items-center"><button className="flex min-w-0 flex-1 items-center gap-4 text-left" onClick={() => view(bill)}><div className="grid h-12 w-12 shrink-0 place-items-center overflow-hidden rounded-xl bg-[#e7eee5] text-[#386a42]">{bill.imageUrl ? <img src={bill.imageUrl} alt="Bill thumbnail" className="h-full w-full object-cover" /> : <FileImage className="h-5 w-5" />}</div><div className="min-w-0"><div className="flex flex-wrap gap-2"><p className="truncate font-semibold text-[#213d29]">{formatCustomerName(bill.customerSalesman, bill.customerName)}</p><State status={bill.status} reason={bill.progressReason} /></div><p className="mt-1 truncate text-sm text-muted-foreground">{bill.shopName} · {bill.customerMobile ?? "No mobile"} · {formatDate(bill.createdAt)}</p><p className={`mt-2 inline-flex items-center gap-1.5 rounded-full px-2 py-1 text-xs font-medium ${reasonTone[bill.progressReason]}`}><span className="h-1.5 w-1.5 rounded-full bg-current" />{reasonLabel[bill.progressReason]}</p></div></button><div className="grid grid-cols-2 gap-x-6 gap-y-2 sm:flex sm:items-center sm:gap-8"><Amount label="Stitching" value={formatMoney(bill.stitchingAmount)} /><Amount label="Balance" value={formatMoney(bill.balanceAmount)} /><p className="col-span-2 max-w-44 text-xs leading-5 text-[#637364] sm:col-span-1">{paymentText(bill)}</p><div className="col-span-2 flex gap-1 sm:col-span-1"><Button variant="outline" size="sm" onClick={() => view(bill)}>Details</Button><Button variant="ghost" size="icon" onClick={() => edit(bill)}><Edit3 className="h-4 w-4" /></Button><Button variant="ghost" size="icon" className="text-destructive hover:text-destructive" onClick={() => remove(bill)}><Trash2 className="h-4 w-4" /></Button></div></div></div></CardContent></Card>; }
function State({ status, reason }: { status: OrderStatus; reason?: ProgressReason }) { const activeReason = reason ?? (status === "completed" ? "order_completed" : "work_in_progress"); return <Badge className={`border-0 ${reasonTone[activeReason]} hover:opacity-90`}><span aria-hidden="true" className={`mr-1.5 inline-block h-1.5 w-1.5 rounded-full ${reasonDot[activeReason]}`} />{reasonLabel[activeReason]}</Badge>; }
function CompactBill({ bill }: { bill: Bill }) { return <div className="flex items-center gap-3 py-4"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#edf2e4] text-[#37643d]"><FileText className="h-5 w-5" /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-[#26402c]">{formatCustomerName(bill.customerSalesman, bill.customerName)}</p><p className="truncate text-xs text-muted-foreground">{bill.shopName} · {formatDate(bill.createdAt)}</p></div><div className="text-right"><p className="text-sm font-semibold text-[#243d2a]">{formatMoney(bill.stitchingAmount)}</p><State status={bill.status} reason={bill.progressReason} /></div></div>; }
function Pulse({ icon: Icon, label, value }: { icon: typeof Store; label: string; value: number }) { return <div className="flex items-center gap-3 rounded-2xl bg-white/65 p-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#c7ed6a] text-[#183322]"><Icon className="h-5 w-5" /></div><p className="flex-1 text-sm font-medium text-[#344738]">{label}</p><span className="font-display text-2xl text-[#183322]">{value}</span></div>; }
function Amount({ label, value }: { label: string; value: string }) { return <div><p className="text-[10px] font-semibold uppercase tracking-[.12em] text-[#809080]">{label}</p><p className="mt-0.5 font-semibold text-[#25402c]">{value}</p></div>; }
function Detail({ icon: Icon, label, value }: { icon: typeof Store; label: string; value: string }) { return <div className="flex gap-3"><div className="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-[#e8efdf] text-[#477049]"><Icon className="h-4 w-4" /></div><div><p className="text-xs text-muted-foreground">{label}</p><p className="mt-0.5 text-sm font-medium text-[#2c4430]">{value}</p></div></div>; }
function Empty({ icon: Icon, title, text, action }: { icon: typeof Store; title: string; text: string; action?: React.ReactNode }) { return <Card className="border-dashed border-[#c7d0c1] bg-white/50"><CardContent className="flex min-h-56 flex-col items-center justify-center p-7 text-center"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#e8f0de] text-[#5b845d]"><Icon className="h-6 w-6" /></div><h2 className="mt-4 font-display text-2xl text-[#28412d]">{title}</h2><p className="mt-2 max-w-sm text-sm leading-6 text-muted-foreground">{text}</p>{action && <div className="mt-5">{action}</div>}</CardContent></Card>; }
function Loading({ count }: { count: number }) { return <>{Array.from({ length: count }, (_, index) => <Card className="animate-pulse border-[#ded8ca] bg-white/60" key={index}><CardContent className="h-28 p-5"><div className="h-4 w-1/3 rounded bg-[#e3e7df]" /><div className="mt-4 h-3 w-2/3 rounded bg-[#edf0e9]" /></CardContent></Card>)}</>; }
function ReportLoading() { return <div className="space-y-7"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Loading count={4} /></div><div className="grid gap-6 lg:grid-cols-2"><Loading count={2} /></div></div>; }
